mapper.select:
select 

from MST_EXCHARGE_QUOTE


		EXCHARGE_CODE like concat(concat('%', #{exchargeCode,jdbcType=VARCHAR}),'%')


	  and to_char(TRADE_DATE,'yyyy-MM-dd') >= #{tradeDateBegin}  


	  and to_char(TRADE_DATE,'yyyy-MM-dd') <= #{tradeDateEnd}  			 


	 and to_char(TRADE_DATE,'yyyy-MM-dd') = #{tradeDate}  			 


order by  exchargeCode,tradeDate
